<?php require 'config/database.php';require 'partials/functions.php';require_login();$pid=(int)($_GET['id']??0);$uid=$_SESSION['user']['id'];$st=$conn->prepare('SELECT id FROM wishlists WHERE user_id=? AND product_id=?');$st->bind_param('ii',$uid,$pid);$st->execute();if($st->get_result()->fetch_assoc()){$d=$conn->prepare('DELETE FROM wishlists WHERE user_id=? AND product_id=?');$d->bind_param('ii',$uid,$pid);$d->execute();}else{$i=$conn->prepare('INSERT IGNORE INTO wishlists(user_id,product_id) VALUES(?,?)');$i->bind_param('ii',$uid,$pid);$i->execute();}header('Location: '.($_SERVER['HTTP_REFERER']??'wishlist.php'));
